1	// statemachine.mjs —— 状态机：所有状态流转的唯一执行者。
2	// 流转表只认 schemas.mjs 里的 TRANSITIONS，表里没有的路一律非法、当场抛错。
3	// 三条硬规矩在这里落地：
4	//   ① 进阶段二必须先有签字文件 + 品味 demo（没谈完 / 没让老板看过能看的 demo 不许开工）；
5	//   ② 里程碑每失败一次记一笔，失败满 INCIDENT_STRIKES 次自动置 incident（三振熔断，等人处理）；
6	//   ③ 全部里程碑 done 时往事件流水记一笔「项目完成」。
7	// 本文件对 .opc/ 的读写全部经 store，绝不直接碰文件系统。
8	
9	import path from 'node:path';
10	import { TRANSITIONS, INCIDENT_STRIKES, WRITE_TYPES, PATHS, TASTE_EXAMPLE_KINDS } from './schemas.mjs';
11	import { readJson, writeJson, appendLine, listOpcDir } from './store.mjs';
12	
13	// 里程碑清单的存放位置以写入类型表声明的为准，不另抄一份路径字面量。
14	const MILESTONES_REL = WRITE_TYPES['phase1-milestones'].path();
15	// 品味 demo 的存放目录（从写入类型表推出，不另抄字面量）。
16	const TASTE_EXAMPLES_REL = path.posix.dirname(WRITE_TYPES['taste-example'].path('占位.html'));
17	
18	// 品味是否留过能看的真实 demo：examples/ 下有没有认得后缀的例子文件。
19	async function hasTasteDemo(root) {
20	  const names = await listOpcDir(root, TASTE_EXAMPLES_REL);
21	  return names.some((n) => Object.keys(TASTE_EXAMPLE_KINDS).some((s) => n.endsWith(s)));
22	}
23	
24	// 非法流转专用错误：CLI 层认出它之后转成 EXIT.ILLEGAL_TRANSITION 退出码。
25	export class IllegalTransition extends Error {
26	  constructor(message) {
27	    super(message);
28	    this.name = 'IllegalTransition';
29	  }
30	}
31	
32	// 查流转表：当前状态到目标状态有没有路。没有就抛非法流转，绝不放行。
33	function assertTransition(kind, from, to) {
34	  const table = TRANSITIONS[kind];
35	  const targets = table[from];
36	  if (!Array.isArray(targets) || !targets.includes(to)) {
37	    throw new IllegalTransition(`${kind} 不允许从「${from}」流转到「${to}」`);
38	  }
39	}
40	
41	// 读 state.json，不存在就报错——它是模板自带的底档，缺了说明项目坏了。
42	async function readState(root) {
43	  const state = await readJson(root, PATHS.state);
44	  if (state === null) {
45	    throw new Error(`找不到 ${PATHS.state}，项目状态档缺失，没法推状态`);
46	  }
47	  return state;
48	}
49	
50	// 状态流转总入口。kind 是对象种类（project/milestone/sprint/tick），
51	// id 指明哪一个（project 全项目只有一个，不用 id），toState 是目标状态。
52	// 返回 {kind, id, from, to, incident}，incident 表示这次流转有没有触发三振熔断。
53	export async function advance(root, kind, id, toState, { actor } = {}) {
54	  if (typeof actor !== 'string' || actor.trim() === '') {
55	    throw new Error('advance 必须注明 actor（这次是谁在推状态）');
56	  }
57	  switch (kind) {
58	    case 'project':
59	      return advanceProject(root, toState, actor);
60	    case 'milestone':
61	      return advanceMilestone(root, id, toState, actor);
62	    case 'sprint':
63	      return advanceSprint(root, id, toState, actor);
64	    case 'tick':
65	      return advanceTick(root, id, toState, actor);
66	    default:
67	      throw new Error(`不认识的对象种类「${kind}」，只认识 project、milestone、sprint、tick`);
68	  }
69	}
70	
71	// 项目阶段流转：phase1 → phase2 → steering → phase2。
72	// 进阶段二的额外前提：阶段一的签字文件必须存在（老板没签字就是没谈完）。
73	// 调向收尾（steering → phase2）的附带动作：熔断随调向解除——这是 incident 的出路①
74	// （出路②是老板签字 resume，在 approvals.mjs 里）。
75	async function advanceProject(root, toState, actor) {
76	  const state = await readState(root);
77	  const from = state.phase;
78	  assertTransition('project', from, toState);
79	  if (from === 'phase1' && toState === 'phase2') {
80	    const signoffRel = WRITE_TYPES['phase1-signoff'].path();
81	    const signoff = await readJson(root, signoffRel);
82	    if (signoff === null) {
83	      throw new Error(`阶段一还没签字（缺 ${signoffRel}），不许进阶段二`);
84	    }
85	    // 品味必须留过能看的真实 demo（examples/ 下至少一个文件）——文字描述不了老板心里想要的，
86	    // 得有 demo 让老板确认过。判定归脚本，不靠嘴上「必须」。
87	    if (!(await hasTasteDemo(root))) {
88	      throw new Error(
89	        '阶段一还没留品味 demo（phase1/taste/examples/ 下一个文件都没有），不许进阶段二——' +
90	          '先 write taste-example 造个能看的 demo 让老板确认'
91	      );
92	    }
93	  }
94	
95	  // 由熔断进的调向，收尾时把熔断解除、肇事里程碑的失败计数清零（宪法：失败计数随调向清零）。
96	  let incidentCleared = false;
97	  if (from === 'steering' && toState === 'phase2' && state.incident !== null && state.incident !== undefined) {
98	    const incident = state.incident;
99	    const milestones = await readJson(root, MILESTONES_REL);
100	    const entry = Array.isArray(milestones) ? milestones.find((m) => m.id === incident.milestone) : undefined;
101	    if (entry) {
102	      entry.fail_count = 0;
103	      await writeJson(root, MILESTONES_REL, milestones, {
104	        actor,
105	        event: `调向收尾：里程碑 ${incident.milestone} 失败计数清零（熔断随调向解除）`
106	      });
107	    } else {
108	      // 调向本来就可能把肇事里程碑作废重组掉——计数无处可清不算错，但要留痕让 audit 查得到。
109	      await appendLine(root, PATHS.events, {
110	        at: new Date().toISOString(),
111	        actor,
112	        event: `调向收尾：熔断指着的里程碑 ${incident.milestone} 已不在清单里，无失败计数可清`
113	      });
114	    }
115	    state.incident = null;
116	    incidentCleared = true;
117	  }
118	
119	  state.phase = toState;
120	  await writeJson(root, PATHS.state, state, { actor, event: `advance:project:${from}→${toState}` });
121	  return { kind: 'project', id: null, from, to: toState, incident: false, incident_cleared: incidentCleared };
122	}
123	
124	// 里程碑状态流转。状态和失败计数都记在里程碑条目上（复盘可查）；
125	// 流转到 failed 时计数加一，满 INCIDENT_STRIKES 次就把 state.incident 置位（三振熔断）；
126	// 流转到 done 且全部里程碑都 done 时，往事件流水记「项目完成」。
127	async function advanceMilestone(root, id, toState, actor) {
128	  const milestones = await readJson(root, MILESTONES_REL);
129	  if (!Array.isArray(milestones)) {
130	    throw new Error(`还没有里程碑清单（${MILESTONES_REL}），没法推里程碑状态`);
131	  }
132	  const entry = milestones.find((m) => m.id === id);
133	  if (!entry) {
134	    throw new Error(`里程碑清单里找不到「${id}」，没法推状态`);
135	  }
136	  const from = entry.status ?? 'planned'; // 没写过状态的里程碑就是刚排期的
137	  assertTransition('milestone', from, toState);
138	  entry.status = toState;
139	
140	  // 离开验收（到 done/failed）就消费掉本次申报标记 claimed_at_tick。转移表里 done/failed 只能自
141	  // verifying 到达，等价于「带一份 verdict 离开验收即销标」，脚本判与手工判两条路径全覆盖。
142	  // 不销标的话，失败里程碑会带着旧标记：precheck 每轮见标记就短路回 acceptance，把没改过的交付物
143	  // 一遍遍重验、永不插入修复（trade M3 反复重验永远失败的根）。
144	  if (toState === 'done' || toState === 'failed') delete entry.claimed_at_tick;
145	
146	  // 失败计数：只增不减，调向或签字解除时才由对应命令清零（不归本文件管）。
147	  let incident = null;
148	  if (toState === 'failed') {
149	    entry.fail_count = (Number.isInteger(entry.fail_count) ? entry.fail_count : 0) + 1;
150	    // 欠一次修复：置 needs_fix，milestone-claim 重报前必须先有一条针对它的 sprint 走到 done 来清它
151	    //（清标动作在 advanceSprint 里）。这就是「失败不许不改就重验，必须先插修复 sprint」的结构闸。
152	    entry.needs_fix = true;
153	    if (entry.fail_count >= INCIDENT_STRIKES) {
154	      incident = { milestone: id, fail_count: entry.fail_count, at: new Date().toISOString() };
155	    }
156	  }
157	  if (toState === 'done') delete entry.needs_fix; // 过了就不欠修复了
158	
159	  await writeJson(root, MILESTONES_REL, milestones, {
160	    actor,
161	    event: `advance:milestone:${id}:${from}→${toState}`
162	  });
163	
164	  if (incident) {
165	    const state = await readState(root);
166	    state.incident = incident;
167	    await writeJson(root, PATHS.state, state, {
168	      actor,
169	      event: `三振熔断：里程碑 ${id} 连续失败 ${incident.fail_count} 次，冻结等人处理`
170	    });
171	  }
172	
173	  if (toState === 'done' && milestones.every((m) => (m.status ?? 'planned') === 'done')) {
174	    await appendLine(root, PATHS.events, {
175	      at: new Date().toISOString(),
176	      actor,
177	      event: '项目完成',
178	      detail: '全部里程碑都已 done'
179	    });
180	  }
181	
182	  return { kind: 'milestone', id, from, to: toState, incident: incident !== null };
183	}
184	
185	// sprint 状态流转：状态记在 sprint 自己的文件里。
186	async function advanceSprint(root, id, toState, actor) {
187	  const rel = WRITE_TYPES['sprint'].path(id);
188	  const sprint = await readJson(root, rel);
189	  if (sprint === null) {
190	    throw new Error(`找不到 sprint「${id}」（${rel}），没法推状态`);
191	  }
192	  const from = sprint.status ?? 'planned'; // 没写过状态的 sprint 就是刚排期的
193	  assertTransition('sprint', from, toState);
194	  // 结构闸（G 项：评审证伪证据闸）：sprint 收尾（done）前必须至少留一条评审证据——
195	  // 不论 verdict，reject 的证据同样算「评审过」（是否要打回重来归 precheck/审计裁，
196	  // 本闸只问「评审过没有」，不在此重复裁定）。
197	  if (toState === 'done') {
