// statemachine.mjs —— 状态机：所有状态流转的唯一执行者。
// 流转表只认 schemas.mjs 里的 TRANSITIONS，表里没有的路一律非法、当场抛错。
// 三条硬规矩在这里落地：
//   ① 进阶段二必须先有签字文件 + 品味 demo（没谈完 / 没让老板看过能看的 demo 不许开工）；
//   ② 里程碑每失败一次记一笔，失败满 INCIDENT_STRIKES 次自动置 incident（三振熔断，等人处理）；
//   ③ 全部里程碑 done 时往事件流水记一笔「项目完成」。
// 本文件对 .opc/ 的读写全部经 store，绝不直接碰文件系统。

import path from 'node:path';
import { TRANSITIONS, INCIDENT_STRIKES, WRITE_TYPES, PATHS, TASTE_EXAMPLE_KINDS } from './schemas.mjs';
import { readJson, writeJson, appendLine, listOpcDir } from './store.mjs';

// 里程碑清单的存放位置以写入类型表声明的为准，不另抄一份路径字面量。
const MILESTONES_REL = WRITE_TYPES['phase1-milestones'].path();
// 品味 demo 的存放目录（从写入类型表推出，不另抄字面量）。
const TASTE_EXAMPLES_REL = path.posix.dirname(WRITE_TYPES['taste-example'].path('占位.html'));

// 品味是否留过能看的真实 demo：examples/ 下有没有认得后缀的例子文件。
async function hasTasteDemo(root) {
  const names = await listOpcDir(root, TASTE_EXAMPLES_REL);
  return names.some((n) => Object.keys(TASTE_EXAMPLE_KINDS).some((s) => n.endsWith(s)));
}

// 非法流转专用错误：CLI 层认出它之后转成 EXIT.ILLEGAL_TRANSITION 退出码。
export class IllegalTransition extends Error {
  constructor(message) {
    super(message);
    this.name = 'IllegalTransition';
  }
}

// 查流转表：当前状态到目标状态有没有路。没有就抛非法流转，绝不放行。
function assertTransition(kind, from, to) {
  const table = TRANSITIONS[kind];
  const targets = table[from];
  if (!Array.isArray(targets) || !targets.includes(to)) {
    throw new IllegalTransition(`${kind} 不允许从「${from}」流转到「${to}」`);
  }
}

// 读 state.json，不存在就报错——它是模板自带的底档，缺了说明项目坏了。
async function readState(root) {
  const state = await readJson(root, PATHS.state);
  if (state === null) {
    throw new Error(`找不到 ${PATHS.state}，项目状态档缺失，没法推状态`);
  }
  return state;
}

// 状态流转总入口。kind 是对象种类（project/milestone/sprint/tick），
// id 指明哪一个（project 全项目只有一个，不用 id），toState 是目标状态。
// 返回 {kind, id, from, to, incident}，incident 表示这次流转有没有触发三振熔断。
export async function advance(root, kind, id, toState, { actor } = {}) {
  if (typeof actor !== 'string' || actor.trim() === '') {
    throw new Error('advance 必须注明 actor（这次是谁在推状态）');
  }
  switch (kind) {
    case 'project':
      return advanceProject(root, toState, actor);
    case 'milestone':
      return advanceMilestone(root, id, toState, actor);
    case 'sprint':
      return advanceSprint(root, id, toState, actor);
    case 'tick':
      return advanceTick(root, id, toState, actor);
    default:
      throw new Error(`不认识的对象种类「${kind}」，只认识 project、milestone、sprint、tick`);
  }
}

// 项目阶段流转：phase1 → phase2 → steering → phase2。
// 进阶段二的额外前提：阶段一的签字文件必须存在（老板没签字就是没谈完）。
// 调向收尾（steering → phase2）的附带动作：熔断随调向解除——这是 incident 的出路①
// （出路②是老板签字 resume，在 approvals.mjs 里）。
async function advanceProject(root, toState, actor) {
  const state = await readState(root);
  const from = state.phase;
  assertTransition('project', from, toState);
  if (from === 'phase1' && toState === 'phase2') {
    const signoffRel = WRITE_TYPES['phase1-signoff'].path();
    const signoff = await readJson(root, signoffRel);
    if (signoff === null) {
      throw new Error(`阶段一还没签字（缺 ${signoffRel}），不许进阶段二`);
    }
    // 品味必须留过能看的真实 demo（examples/ 下至少一个文件）——文字描述不了老板心里想要的，
    // 得有 demo 让老板确认过。判定归脚本，不靠嘴上「必须」。
    if (!(await hasTasteDemo(root))) {
      throw new Error(
        '阶段一还没留品味 demo（phase1/taste/examples/ 下一个文件都没有），不许进阶段二——' +
          '先 write taste-example 造个能看的 demo 让老板确认'
      );
    }
  }

  // 由熔断进的调向，收尾时把熔断解除、肇事里程碑的失败计数清零（宪法：失败计数随调向清零）。
  let incidentCleared = false;
  if (from === 'steering' && toState === 'phase2' && state.incident !== null && state.incident !== undefined) {
    const incident = state.incident;
    const milestones = await readJson(root, MILESTONES_REL);
    const entry = Array.isArray(milestones) ? milestones.find((m) => m.id === incident.milestone) : undefined;
    if (entry) {
      entry.fail_count = 0;
      await writeJson(root, MILESTONES_REL, milestones, {
        actor,
        event: `调向收尾：里程碑 ${incident.milestone} 失败计数清零（熔断随调向解除）`
      });
    } else {
      // 调向本来就可能把肇事里程碑作废重组掉——计数无处可清不算错，但要留痕让 audit 查得到。
      await appendLine(root, PATHS.events, {
        at: new Date().toISOString(),
        actor,
        event: `调向收尾：熔断指着的里程碑 ${incident.milestone} 已不在清单里，无失败计数可清`
      });
    }
    state.incident = null;
    incidentCleared = true;
  }

  state.phase = toState;
  await writeJson(root, PATHS.state, state, { actor, event: `advance:project:${from}→${toState}` });
  return { kind: 'project', id: null, from, to: toState, incident: false, incident_cleared: incidentCleared };
}

// 里程碑状态流转。状态和失败计数都记在里程碑条目上（复盘可查）；
// 流转到 failed 时计数加一，满 INCIDENT_STRIKES 次就把 state.incident 置位（三振熔断）；
// 流转到 done 且全部里程碑都 done 时，往事件流水记「项目完成」。
async function advanceMilestone(root, id, toState, actor) {
  const milestones = await readJson(root, MILESTONES_REL);
  if (!Array.isArray(milestones)) {
    throw new Error(`还没有里程碑清单（${MILESTONES_REL}），没法推里程碑状态`);
  }
  const entry = milestones.find((m) => m.id === id);
  if (!entry) {
    throw new Error(`里程碑清单里找不到「${id}」，没法推状态`);
  }
  const from = entry.status ?? 'planned'; // 没写过状态的里程碑就是刚排期的
  assertTransition('milestone', from, toState);
  entry.status = toState;

  // 离开验收（到 done/failed）就消费掉本次申报标记 claimed_at_tick。转移表里 done/failed 只能自
  // verifying 到达，等价于「带一份 verdict 离开验收即销标」，脚本判与手工判两条路径全覆盖。
  // 不销标的话，失败里程碑会带着旧标记：precheck 每轮见标记就短路回 acceptance，把没改过的交付物
  // 一遍遍重验、永不插入修复（trade M3 反复重验永远失败的根）。
  if (toState === 'done' || toState === 'failed') delete entry.claimed_at_tick;

  // 失败计数：只增不减，调向或签字解除时才由对应命令清零（不归本文件管）。
  let incident = null;
  if (toState === 'failed') {
    entry.fail_count = (Number.isInteger(entry.fail_count) ? entry.fail_count : 0) + 1;
    // 欠一次修复：置 needs_fix，milestone-claim 重报前必须先有一条针对它的 sprint 走到 done 来清它
    //（清标动作在 advanceSprint 里）。这就是「失败不许不改就重验，必须先插修复 sprint」的结构闸。
    entry.needs_fix = true;
    if (entry.fail_count >= INCIDENT_STRIKES) {
      incident = { milestone: id, fail_count: entry.fail_count, at: new Date().toISOString() };
    }
  }
  if (toState === 'done') delete entry.needs_fix; // 过了就不欠修复了

  await writeJson(root, MILESTONES_REL, milestones, {
    actor,
    event: `advance:milestone:${id}:${from}→${toState}`
  });

  if (incident) {
    const state = await readState(root);
    state.incident = incident;
    await writeJson(root, PATHS.state, state, {
      actor,
      event: `三振熔断：里程碑 ${id} 连续失败 ${incident.fail_count} 次，冻结等人处理`
    });
  }

  if (toState === 'done' && milestones.every((m) => (m.status ?? 'planned') === 'done')) {
    await appendLine(root, PATHS.events, {
      at: new Date().toISOString(),
      actor,
      event: '项目完成',
      detail: '全部里程碑都已 done'
    });
  }

  return { kind: 'milestone', id, from, to: toState, incident: incident !== null };
}

// sprint 状态流转：状态记在 sprint 自己的文件里。
async function advanceSprint(root, id, toState, actor) {
  const rel = WRITE_TYPES['sprint'].path(id);
  const sprint = await readJson(root, rel);
  if (sprint === null) {
    throw new Error(`找不到 sprint「${id}」（${rel}），没法推状态`);
  }
  const from = sprint.status ?? 'planned'; // 没写过状态的 sprint 就是刚排期的
  assertTransition('sprint', from, toState);
  // 结构闸（G 项：评审证伪证据闸）：sprint 收尾（done）前必须至少留一条评审证据——
  // 不论 verdict，reject 的证据同样算「评审过」（是否要打回重来归 precheck/审计裁，
  // 本闸只问「评审过没有」，不在此重复裁定）。
  if (toState === 'done') {
    const reviews = Array.isArray(sprint.reviews) ? sprint.reviews : [];
    if (reviews.length === 0) {
      throw new Error(
        `sprint「${id}」还没有评审证据（reviews[] 是空的），不许收尾——` +
          '先 write review-evidence 记一笔评审员试图证伪时做了什么、看到了什么'
      );
    }
  }
  sprint.status = toState;
  await writeJson(root, rel, sprint, { actor, event: `advance:sprint:${id}:${from}→${toState}` });
  // 修复 sprint 走到 done 即清掉其里程碑的「欠修复」标记：失败里程碑重报须先有一条 sprint done。
  // 放宽匹配——不认精确 verdict tag，该里程碑名下任一 sprint done 即视为已尝试修复（sprint 永远
  // 可做，闸不会死锁）。只清正欠修复（needs_fix）的，不碰别的。
  if (toState === 'done' && typeof sprint.milestone === 'string') {
    const milestones = await readJson(root, MILESTONES_REL);
    if (Array.isArray(milestones)) {
      const m = milestones.find((x) => x.id === sprint.milestone);
      if (m && m.needs_fix === true) {
        delete m.needs_fix;
        await writeJson(root, MILESTONES_REL, milestones, {
          actor,
          event: `修复 sprint ${id} done，清里程碑 ${sprint.milestone} 的欠修复标记`
        });
      }
    }
  }
  return { kind: 'sprint', id, from, to: toState, incident: false };
}

// tick 状态流转：正式档在 ticks/<轮次>.json。
// 一轮 tick 开跑后不一定立刻有正式档（收尾时才组装），所以没档的 tick 视作 started。
async function advanceTick(root, id, toState, actor) {
  const rel = PATHS.tick(id);
  const tick = (await readJson(root, rel)) ?? {};
  const from = tick.status ?? 'started';
  assertTransition('tick', from, toState);
  tick.status = toState;
  await writeJson(root, rel, tick, { actor, event: `advance:tick:${id}:${from}→${toState}` });
  return { kind: 'tick', id, from, to: toState, incident: false };
}

// 指定活跃里程碑：只有 planned（排期中）或 failed（失败待重来）的里程碑才能被指上，
// 干完的、作废的、验收中的都不行。写 state.active_milestone 指针。
export async function activateMilestone(root, id, { actor = '脚本' } = {}) {
  const milestones = await readJson(root, MILESTONES_REL);
  if (!Array.isArray(milestones)) {
    throw new Error(`还没有里程碑清单（${MILESTONES_REL}），没法指定活跃里程碑`);
  }
  const entry = milestones.find((m) => m.id === id);
  if (!entry) {
    throw new Error(`里程碑清单里找不到「${id}」，没法设为活跃`);
  }
  const status = entry.status ?? 'planned';
  if (status !== 'planned' && status !== 'failed') {
    throw new Error(`里程碑「${id}」当前状态是「${status}」，只有 planned 或 failed 的里程碑才能设为活跃`);
  }
  const state = await readState(root);
  state.active_milestone = id;
  await writeJson(root, PATHS.state, state, { actor, event: `activate-milestone:${id}` });
  return { active_milestone: id };
}

